const body = $input.item.json.body || {};
const change = body.entry?.[0]?.changes?.[0]?.value;

let leadgenId = change?.leadgen_id || body.leadgen_id || null;
let formId = change?.form_id || body.form_id || 'default_form';
let adId = change?.ad_id || body.ad_id || 'default_ad';
let rawPhone = body.phone || body.phone_number || change?.phone_number || '';
let name = body.name || body.full_name || change?.full_name || 'Interested Buyer';

let clean = String(rawPhone).replace(/[^0-9+]/g, '');
if (clean.length === 10) clean = '+91' + clean;
else if (!clean.startsWith('+') && clean.length > 10) clean = '+' + clean;

const valid = /^\+[1-9]\d{9,14}$/.test(clean);

return {
  json: {
    leadgen_id: leadgenId,
    form_id: formId,
    ad_id: adId,
    name: name,
    phone_e164: valid ? clean : null,
    phone_valid: valid,
    project_name: 'Grand Crest Villa Plots'
  }
};

const rows = $input.all();
const isDuplicate = rows.some(r => r.json && r.json.id);
const norm = $('Normalize Meta Lead Record').first().json;

return {
  json: {
    ...norm,
    is_duplicate: isDuplicate
  }
};

const body = $input.item.json.body || {};
const entry = body.entry?.[0]?.changes?.[0]?.value;
const message = entry?.messages?.[0];
const status = entry?.statuses?.[0];

// 1. Handle delivery status updates (sent, delivered, read)
if (status && !message) {
  return {
    json: {
      is_status_event: true,
      status_value: status.status || null,
      provider_message_id: status.id || null,
      phone: null,
      text: '',
      button_id: null,
      msg_type: 'status'
    }
  };
}

// 2. Extract content from text, quick-reply, or interactive button replies
let text = '';
let buttonId = null;
const msgType = message?.type || 'unknown';

if (msgType === 'text') {
  text = message.text?.body || '';
} else if (msgType === 'interactive') {
  buttonId = message.interactive?.button_reply?.id || message.interactive?.list_reply?.id || null;
  text = message.interactive?.button_reply?.title || message.interactive?.list_reply?.title || '';
} else if (msgType === 'button') {
  buttonId = message.button?.payload || null;
  text = message.button?.text || '';
}

// 3. Clean and format the phone number into E.164 (+91...)
let rawFrom = message?.from || '';
let phone = rawFrom.replace(/[^0-9+]/g, '');

if (phone.length === 10) {
  phone = '+91' + phone;
} else if (phone.length > 10 && !phone.startsWith('+')) {
  phone = '+' + phone;
}

// Safeguard: Prevent empty inputs from becoming a bare "+"
if (!phone || phone === '+' || phone.length < 11) {
  phone = null;
}

return {
  json: {
    is_status_event: false,
    phone: phone,
    text: text.trim(),
    button_id: buttonId,
    msg_type: msgType,
    provider_message_id: message?.id || null
  }
};

