const convo = $input.first().json;
const norm = $('Normalize WhatsApp Reply').first().json;
const btn = norm.button_id || '';
const text = (norm.text || '').toLowerCase();
const step = convo.qualification_step;

let field = null;
let value = null;
let valid = false;
let nextStep = null;

if (step === 'AWAITING_PURPOSE') {
  field = 'purpose';
  if (btn === 'purpose_invest' || text.includes('invest')) value = 'invest';
  else if (btn === 'purpose_build' || text.includes('build')) value = 'build';
  else if (btn === 'purpose_explore' || text.includes('explore')) value = 'explore';
  if (value) { valid = true; nextStep = 'AWAITING_BUDGET'; }

} else if (step === 'AWAITING_BUDGET') {
  field = 'budget';
  if (btn === 'budget_75_plus' || text.includes('75') || text.includes('> 75')) value = 'budget_75_plus';
  else if (btn === 'budget_50_75' || text.includes('50') || text.includes('75')) value = 'budget_50_75';
  else if (btn === 'budget_under_50' || text.includes('< 50') || text.includes('under')) value = 'budget_under_50';
  if (value) { valid = true; nextStep = 'AWAITING_TIMELINE'; }

} else if (step === 'AWAITING_TIMELINE') {
  field = 'timeline';
  if (btn === 'timeline_immediate' || btn === 'timeline_0_3m' || text.includes('3 month') || text.includes('immediate')) {
    value = 'timeline_immediate';
  } else if (btn === 'timeline_3_6m' || text.includes('6 month') || text.includes('3 to 6')) {
    value = 'timeline_3_6m';
  } else if (btn === 'timeline_gt_6m' || text.includes('> 6') || text.includes('later') || text.includes('exploring')) {
    value = 'timeline_gt_6m';
  }
  if (value) { valid = true; nextStep = 'AWAITING_FIT'; }

} else if (step === 'AWAITING_FIT') {
  field = 'project_fit';
  if (btn === 'fit_yes' || text.includes('yes') || text.includes('fits') || text.includes('agree')) {
    value = 'fit_yes';
  } else if (btn === 'fit_no' || text.includes('no') || text.includes('differ') || text.includes('change')) {
    value = 'fit_no';
  }
  if (value) { valid = true; nextStep = 'COMPLETED'; }
}

return {
  json: {
    valid: valid,
    field: field,
    value: value,
    next_step: nextStep,
    conversation_id: convo.conversation_id,
    contact_id: convo.contact_id,
    phone_e164: convo.phone_e164,
    name: convo.name
  }
};

// 1. Convert PostgreSQL rows into a clean key-value map
const items = $input.all();
const answers = {};

for (const item of items) {
  const row = item.json;
  if (row.field && row.value) {
    answers[row.field] = row.value;
  }
}

const budget = answers.budget || '';
const timeline = answers.timeline || '';
const fit = answers.project_fit || '';
const purpose = answers.purpose || '';

// 2. Evaluation Rules
// HOT: Budget 75L+ AND Timeline within 3 months AND Fit is Yes
const isHotBudget = (budget === 'budget_75_plus');
const isImmediateTimeline = (timeline === 'timeline_immediate' || timeline === 'timeline_0_3m');
const isFit = (fit === 'fit_yes');

let outcome = 'warm'; // Default fallback

if (isHotBudget && isImmediateTimeline && isFit) {
  outcome = 'hot';
} else if (budget === 'budget_under_50' || timeline === 'timeline_gt_6m' || fit === 'fit_no') {
  outcome = 'cold';
}

return {
  json: {
    outcome: outcome,
    answers: answers,
    is_hot: outcome === 'hot',
    is_warm: outcome === 'warm',
    is_cold: outcome === 'cold'
  }
};

