FROM leadqual_sw.conversations WHERE id = $1;

WITH eligible_rm AS (
  SELECT rm_id, rm_name, slack_user_id FROM leadqual_sw.rm_roster 
  WHERE active = true ORDER BY last_assigned_at ASC NULLS FIRST LIMIT 1
),
assigned AS (
  UPDATE leadqual_sw.rm_roster SET last_assigned_at = NOW() WHERE rm_id = (SELECT rm_id FROM eligible_rm)
)
