const payload = $('Loop Over Claimed Actions').item.json.payload || {};
const ctx = $input.first().json;
const kind = payload.kind;
const step = payload.step;

let messageType = 'interactive';
let textBody = '';
let buttons = [];

if (kind === 'initial_outreach') {
  textBody = `Hi ${ctx.contact_name || 'Valued Buyer'}! Thank you for inquiring about ${ctx.project_name}.\n\n📄 E-Brochure & Master Plan: https://example.com/grand-crest-brochure.pdf\n\nAre you looking to invest, build immediately, or explore?`;
  buttons = [
    { id: 'purpose_invest', title: 'Invest' },
    { id: 'purpose_build', title: 'Build Immediately' },
    { id: 'purpose_explore', title: 'Just Exploring' }
  ];
} else if (kind === 'question') {
  if (step === 'AWAITING_BUDGET') {
    textBody = `Plots at ${ctx.project_name} start from ₹70 Lakhs.\n\nPlease select your comfortable investment budget bracket:`;
    buttons = [
      { id: 'budget_30_50', title: '₹30L – ₹50L' },
      { id: 'budget_50_75', title: '₹50L – ₹75L' },
      { id: 'budget_75_plus', title: '₹75L+' }
    ];
  } else if (step === 'AWAITING_TIMELINE') {
    textBody = 'When are you planning to finalize your purchase?';
    buttons = [
      { id: 'timeline_30', title: 'Within 30 Days' },
      { id: 'timeline_90', title: 'Within 90 Days' },
      { id: 'timeline_later', title: 'Later / Exploring' }
    ];
  } else if (step === 'AWAITING_PROJECT_FIT') {
    textBody = `Project Details:\n• Gated Community Villa Plots\n• Clear Title & Ready Infrastructure\n\nDoes this match your property requirements?`;
    buttons = [
      { id: 'fit_yes', title: 'Yes, Matches' },
      { id: 'fit_no', title: 'No, Need Other' }
    ];
  } else if (step === 'AWAITING_CALLBACK') {
    textBody = 'Would you like our Senior Relationship Manager to call you with available plot inventory?';
    buttons = [
      { id: 'call_yes', title: 'Yes, Arrange Call' },
      { id: 'call_no', title: 'No, Text Only' }
    ];
  }
} else if (kind === 'hot_confirmation') {
  messageType = 'text';
  textBody = `Thank you, ${ctx.contact_name || 'Buyer'}! Your requirement is a confirmed match for ${ctx.project_name}.\n\nOur Senior Relationship Manager is prioritizing your file and will contact you within 15 minutes to share plot availability.`;
} else if (kind === 'warm_ack') {
  messageType = 'text';
  textBody = `Thank you for sharing your timeline! We have noted your preferences and will share developmental updates and price sheets periodically on WhatsApp.`;
} else if (kind === 'polite_close') {
  messageType = 'text';
  textBody = `Thank you for letting us know! Because plots at ${ctx.project_name} start from ₹70 Lakhs, we have archived your details for upcoming affordable phases. Have a great day!`;
} else if (kind === 'clarification') {
  messageType = 'text';
  textBody = `Please tap one of the option buttons above to help us guide you to the right plots, or reply 'HUMAN' to speak with front-desk staff.`;
}

return {
  json: {
    ...ctx,
    message_type: messageType,
    body_text: textBody,
    buttons
  }
};

